// model/source-records.mjs -- source records and reducers, form state and the Sources transitions. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  str, asList, fnv1a32
} from "./text.mjs"
import {
  copyGuide, withQuery, withMode
} from "./browse.mjs"
import {
  emptyState, pendingEpgRecord, pendingEpgOf, withPendingEpg, cloneState
} from "./state.mjs"
import {
  clampSetting, settingsFrom, entryInputForm, RETIRED_SETTINGS,
  ownedEntryPatch, entryFlushDisposition, ownedWriteMode, retiredInputsToKeep,
  patchInputsToKeep
} from "./settings.mjs"
import {
  CACHE_LAYOUT, MAX_SOURCES, MAX_SOURCE_URL, MAX_LABEL, LIMITS,
  SOURCE_ORIGINS, FORM_LIMITS, CONTROL_RE, capLength, sanitizeInput,
  capCodePoints, sourceErrorMessage, validateSourceUrl, isUrlField, sourceKey,
  isSourceKey, findSource, findSourceByUrl, allocateSourceKey, deriveLabel,
  uniqueLabel, validateLabel, maskUrl, sourceView, sourceViews
} from "./sources.mjs"

// ---- state records and reducers (ARCHITECTURE-SOURCES 2.1, 3.5)

// `search` rather than `test`: CONTROL_RE is global (stateful lastIndex).
function hasControlChars(text) {
  return str(text).search(CONTROL_RE) !== -1
}

// Console line for a record the reader drops (D-SRC-09): the key only,
// never the URL. The model is otherwise silent; node has a console too.
function warnState(message) {
  if (typeof console !== "undefined" && console && typeof console.warn === "function") console.warn("omarchy-iptv: state: " + message)
}

// A record whose `url` carries a control character (NUL, CR, ...) is
// dropped: it would reach the helper's argv and can never match a key
// (D-SRC-09). A control character in `epgUrl` clears that field only.
function normalizeSourceRecord(raw) {
  if (!raw || typeof raw !== "object") return null
  var key = str(raw.key)
  var url = str(raw.url)
  if (!isSourceKey(key) || url === "" || url.length > MAX_SOURCE_URL || hasControlChars(url)) return null
  var kind = str(raw.kind)
  if (kind !== "http" && kind !== "file") kind = url.charAt(0) === "/" ? "file" : "http"
  var epg = str(raw.epgUrl)
  if (epg.length > MAX_SOURCE_URL || hasControlChars(epg)) epg = ""
  var origin = str(raw.origin)
  if (SOURCE_ORIGINS.indexOf(origin) === -1) origin = "guide"
  var label = capCodePoints(sanitizeInput(raw.label), MAX_LABEL)
  if (label === "") label = deriveLabel(url, kind)
  var out = {
    key: key,
    url: url,
    epgUrl: epg,
    kind: kind,
    label: label,
    labelCustom: raw.labelCustom === true,
    origin: origin,
    addedAt: Math.max(0, Math.floor(Number(raw.addedAt) || 0)),
    lastUsed: Math.max(0, Math.floor(Number(raw.lastUsed) || 0)),
    fetchedAt: Math.max(0, Math.floor(Number(raw.fetchedAt) || 0)),
    channelCount: Math.max(0, Math.floor(Number(raw.channelCount) || 0)),
    groupCount: Math.max(0, Math.floor(Number(raw.groupCount) || 0))
  }
  // D-SINK-19 round 9, R19c: when this record's guide URL was last SET, in
  // milliseconds -- by the add form at submit, by the edit form, or by the
  // adoption of a CLI input (its seenAt). Carried only when known (> 0): a
  // record written before R19 has none and reads as 0, and a record that
  // never had one serializes exactly as it did.
  var setAt = epgSetAtOf(raw)
  if (setAt > 0) out.epgSetAt = setAt
  return out
}

// A record's `epgSetAt` as a number, 0 for absent or junk (R19c).
function epgSetAtOf(rec) {
  return Math.max(0, Math.trunc(Number(rec && rec.epgSetAt)) || 0)
}

function copySourceRecord(rec, patch) {
  var out = {}
  for (var k in rec) out[k] = rec[k]
  var p = patch || {}
  for (var q in p) out[q] = p[q]
  return out
}

function replaceSource(state, key, patch) {
  var st = state || emptyState()
  var list = asList(st.sources)
  var out = []
  for (var i = 0; i < list.length; i++) out.push(list[i] && str(list[i].key) === str(key) ? copySourceRecord(list[i], patch) : list[i])
  return cloneState(st, { sources: out })
}

function nowInt(nowSec) {
  return Math.max(0, Math.floor(Number(nowSec) || 0))
}

function sourceLabels(state) {
  return asList(state ? state.sources : []).map(function(s) { return { id: str(s.key), label: str(s.label) } })
}

function reducerFail(state, code, key, opts) {
  return { ok: false, code: code, message: sourceErrorMessage(code, opts), state: state, key: str(key) }
}

// fields = { playlistUrl, epgUrl, label, origin }. Codes: the UX 5.4 URL
// codes, `label_too_long`, `label_taken` (a typed label that collides),
// `duplicate` (with the existing key), `too_many`. An empty label derives
// one from the URL and keeps `labelCustom: false`.
function addSource(state, fields, nowSec) {
  var st = cloneState(state)
  var f = fields || {}
  var pv = validateSourceUrl(f.playlistUrl)
  if (!pv.ok) return reducerFail(st, pv.code, "")
  var ev = validateSourceUrl(f.epgUrl, { kind: "epg" })
  if (!ev.ok) return reducerFail(st, ev.code, "", { field: "epg" })
  var dup = findSourceByUrl(st.sources, pv.url)
  if (dup) return reducerFail(st, "duplicate", dup.key, { label: dup.label })
  if (st.sources.length >= MAX_SOURCES) return reducerFail(st, "too_many", "")
  var lv = validateLabel(f.label, sourceLabels(st), "")
  if (!lv.ok) return reducerFail(st, lv.code, "", { label: lv.label })
  var origin = SOURCE_ORIGINS.indexOf(str(f.origin)) === -1 ? "guide" : str(f.origin)
  var label = lv.label !== "" ? lv.label : uniqueLabel(deriveLabel(pv.url, pv.kind), sourceLabels(st))
  var now = nowInt(nowSec)
  var key = allocateSourceKey(st.sources, pv.url)
  var rec = {
    key: key, url: pv.url, epgUrl: ev.url, kind: pv.kind, label: label, labelCustom: lv.label !== "",
    origin: origin, addedAt: now, lastUsed: now, fetchedAt: 0, channelCount: 0, groupCount: 0
  }
  // R19c: a guide URL the form carries is SET at submit time -- the moment
  // this is called (`fields.epgSetAt`, ms), never the probe's commit. A form
  // left blank sets nothing, so a pending input still lands on it (E4).
  var setAt = epgSetAtOf(f)
  if (ev.url !== "" && setAt > 0) rec.epgSetAt = setAt
  return { ok: true, code: "ok", message: "", state: cloneState(st, { sources: st.sources.concat([rec]) }), key: key }
}

// fields = { label, playlistUrl, epgUrl } (each optional). A label change
// sets `labelCustom` (an empty label re-derives it). A changed playlist URL
// yields a NEW record (new key, `fetchedAt: 0`, label / addedAt copied) and
// leaves the old one in place until the service confirms the probe;
// `replacedKey` names the old record. An edit never counts against
// MAX_SOURCES: the replacement takes the old record's place, so the
// transient 51st entry is not a `too_many` (the service keeps it in memory
// and drops the old record before the new one lands in the history).
function updateSource(state, key, fields, nowSec) {
  var st = cloneState(state)
  var rec = findSource(st.sources, key)
  if (!rec) return { ok: false, code: "unknown_source", message: sourceErrorMessage("unknown_source"), state: st, key: str(key), urlChanged: false, replacedKey: "" }
  var f = fields || {}
  var patch = {}
  if (f.label !== undefined) {
    var lv = validateLabel(f.label, sourceLabels(st), rec.key)
    if (!lv.ok) return { ok: false, code: lv.code, message: lv.message, state: st, key: rec.key, urlChanged: false, replacedKey: "" }
    patch.label = lv.label !== "" ? lv.label : uniqueLabel(deriveLabel(rec.url, rec.kind), sourceLabels(st), rec.key)
    patch.labelCustom = lv.label !== ""
  }
  if (f.epgUrl !== undefined) {
    var ev = validateSourceUrl(f.epgUrl, { kind: "epg" })
    if (!ev.ok) return { ok: false, code: ev.code, message: ev.message, state: st, key: rec.key, urlChanged: false, replacedKey: "" }
    patch.epgUrl = ev.url
    // R19c: the edit form SETS the guide URL only when it changes it. The
    // form sends every field on every submit, so a label edit that carries
    // the guide URL back unchanged is not a later explicit input for it.
    var editAt = epgSetAtOf(f)
    if (ev.url !== str(rec.epgUrl) && editAt > 0) patch.epgSetAt = editAt
  }
  var urlChanged = false
  var newKey = rec.key
  if (f.playlistUrl !== undefined) {
    var pv = validateSourceUrl(f.playlistUrl)
    if (!pv.ok) return { ok: false, code: pv.code, message: pv.message, state: st, key: rec.key, urlChanged: false, replacedKey: "" }
    if (pv.url !== rec.url) {
      var dup = findSourceByUrl(st.sources, pv.url)
      if (dup) return { ok: false, code: "duplicate", message: sourceErrorMessage("duplicate", { label: dup.label }), state: st, key: str(dup.key), urlChanged: false, replacedKey: "" }
      urlChanged = true
      newKey = allocateSourceKey(st.sources, pv.url)
      var replacement = copySourceRecord(rec, patch)
      replacement.key = newKey
      replacement.url = pv.url
      replacement.kind = pv.kind
      replacement.fetchedAt = 0
      replacement.channelCount = 0
      replacement.groupCount = 0
      replacement.lastUsed = nowInt(nowSec)
      if (!replacement.labelCustom) replacement.label = uniqueLabel(deriveLabel(pv.url, pv.kind), sourceLabels(st))
      return { ok: true, code: "ok", message: "", state: cloneState(st, { sources: st.sources.concat([replacement]) }), key: newKey, urlChanged: true, replacedKey: rec.key }
    }
  }
  return { ok: true, code: "ok", message: "", state: replaceSource(st, rec.key, patch), key: rec.key, urlChanged: urlChanged, replacedKey: "" }
}

// Removing the ACTIVE record clears the pointer in the state this returns
// (D-SINK-19 repair, R3). The helper's `remove_source_record` has done the
// same since the key existed; this side rebuilt through cloneState, which
// carries `activeKey` faithfully, so the state named a record it no longer
// held. activeKeyOf resolves that to "no active source" on every read, which
// is why nothing crashed -- but a pointer that only reads as cleared is the
// shape the review called a dangling key, and the file said otherwise. The
// shared fixture's `remove` cases run through both implementations.
function removeSource(state, key) {
  var st = cloneState(state)
  var removed = findSource(st.sources, key)
  if (!removed) return { state: st, removed: null }
  var out = []
  for (var i = 0; i < st.sources.length; i++) if (st.sources[i] !== removed) out.push(st.sources[i])
  var next = cloneState(st, { sources: out })
  return { state: withActiveKey(next, activeKeyOf(next)), removed: removed }
}

function touchSource(state, key, nowSec) {
  var st = cloneState(state)
  if (!findSource(st.sources, key)) return st
  return replaceSource(st, key, { lastUsed: nowInt(nowSec) })
}

// The timestamp a status carries (fetchedAt, else generatedAt), 0 for none.
function statusFetchedAt(status) {
  var fetched = Math.floor(Number(status && status.fetchedAt) || 0)
  if (fetched <= 0) fetched = Math.floor(Number(status && status.generatedAt) || 0)
  return fetched > 0 ? fetched : 0
}

// True when a successful status carries counts or a timestamp the record
// does not have yet, so the service adopts them when the active source's
// playlist-status.json loads (the migrated cache, a CLI-reconciled record
// fetched by the startup refresh: D-SRC-01) without rewriting state.json
// on every load.
function sourceStatsDiffer(rec, status) {
  if (!rec || !status || status.ok !== true) return false
  var fetched = statusFetchedAt(status)
  var recFetched = Math.max(0, Math.floor(Number(rec.fetchedAt) || 0))
  if (fetched > 0 ? fetched !== recFetched : recFetched === 0) return true
  return Math.max(0, Math.floor(Number(status.channelCount) || 0)) !== Math.max(0, Math.floor(Number(rec.channelCount) || 0))
    || Math.max(0, Math.floor(Number(status.groupCount) || 0)) !== Math.max(0, Math.floor(Number(rec.groupCount) || 0))
}

// Copies the counts of a successful `playlist` status onto the record so
// the list shows them without opening N status files. `nowSec` is the
// fallback when the status carries no fetchedAt.
function withSourceStats(state, key, status, nowSec) {
  var st = cloneState(state)
  if (!status || status.ok !== true || !findSource(st.sources, key)) return st
  var fetched = statusFetchedAt(status)
  if (fetched <= 0) fetched = Math.max(1, nowInt(nowSec))
  return replaceSource(st, key, {
    fetchedAt: fetched,
    channelCount: Math.max(0, Math.floor(Number(status.channelCount) || 0)),
    groupCount: Math.max(0, Math.floor(Number(status.groupCount) || 0))
  })
}

// ---- the active source, by KEY (D-SINK-19)
//
// D4 gave source identity to the normalized playlist URL and named the active
// source by it, which meant the host's `shell.json` had to hold a provider
// credential for the plugin to know which source was active. D-SINK-18
// contained that by making the file private first; this removes the reason.
// The IDENTITY half of D4 is untouched -- duplicates are still detected on
// the normalized URL, the key is still `fnv1a32` of it -- and only the
// PERSISTENCE half is overturned: the active source is named by its key, in
// the plugin's own 0600 state file.
//
// A key read back from the file is NOT trusted to name a record: a `state
// source remove` through the CLI, a hand-edited file, or an eviction can all
// leave one dangling. The resolution is here, in one place, so no caller has
// to remember to check.
// A STRING or nothing, and the type test is not defensive clutter: it is the
// shared fixture's finding. `str()` coerces, and the coercions land inside the
// key grammar -- the number 12345678 becomes "12345678", eight hex-valid
// characters, and the one-element array ["d990c2e4"] becomes "d990c2e4". The
// helper's mirror requires `isinstance(raw, str)`, so a hand-edited or
// foreign-written state.json would have read as configured on one side and
// unconfigured on the other. Caught by the shared active-key fixture (dev
// branch) running both readers on the same bytes (rule 12); it was not caught
// by review.
function activeKeyText(value) {
  if (typeof value !== "string") return ""
  var key = value.replace(/^\s+|\s+$/g, "")
  return isSourceKey(key) ? key : ""
}

// The active source's key: what the state says, when it still names a record
// this state carries. "" means "no active source", which is what `configured`
// now asks about.
function activeKeyOf(state) {
  var key = activeKeyText(state ? state.activeKey : "")
  if (key === "") return ""
  return findSource(state ? state.sources : [], key) ? key : ""
}

// The active source's record, or null.
function activeSourceRecord(state) {
  return findSource(state ? state.sources : [], activeKeyOf(state))
}

// Set (or clear) the active key. Goes through cloneState like every other
// reducer, so the key survives a favourites or recents write.
function withActiveKey(state, key) {
  var want = activeKeyText(key)
  var st = state || emptyState()
  if (str(st.activeKey) === want) return st
  return cloneState(st, { activeKey: want })
}

// D16 / SR8 after D-SINK-19: when does a REFUSED input become the guide's
// error state and stop the helper?
//
// Only when there is no active source to show instead. D16 was written when
// the setting WAS the active source, so a typo in `omarchy bar set ...
// playlistUrl` legitimately emptied the guide: nothing was configured any
// more. The setting is an input now and the active source is in state.json,
// so the same typo must leave a working source alone -- and the error must
// still be the body when the bad value is the only configuration there is.
//
// In the model rather than as an inline expression in Service.qml for the
// reason rule 12 gives: a decision a test cannot call is a decision nothing
// checks.
function invalidInputBlocks(invalid, activeKey) {
  if (!invalid) return false
  return activeKeyText(activeKey) === ""
}

// D-SINK-19. WHAT A SETTINGS CHANGE MEANS FOR THE ACTIVE SOURCE.
//
// Lifted out of Service.qml's reconcile() deliberately (rule 12): it is pure
// logic, it is the single most dangerous decision in this change, and inside
// a QML component no test can call it.
//
// REPAIRED after the adversarial review (lead ruling R1). The first version
// answered "migrate" for every first or forced reconcile and "migrate" never
// read the entry's URL when the state already held a key -- so a URL set with
// `omarchy bar set ... playlistUrl` while the shell was down was discarded on
// the next start and then stripped out of shell.json by the plugin's own
// write. The user's input was deleted and nothing said so.
//
// The rule now: a URL on the bar entry that this service has NOT ALREADY
// CONSUMED is fresh user input and is adopted before any key is trusted. The
// plugin strips URLs on every own write, so a URL can only be on the entry
// because a user put it there -- with one qualification the host imposes:
// barConfig is published ONE WRITE BEHIND and the plugin's own write never
// echoes (rule 9), so after the strip the host keeps publishing the SAME URL
// until somebody else writes. That stale echo is what `lastPlaylist` is for.
// A value equal to the one this service already adopted is consumed, not a
// command; a value that differs, or any value on the first reconcile of a
// service (the shell start, where the published entry IS the file), is fresh.
//
//   adopt    the entry carries a playlist URL this service has not consumed
//            (first reconcile, or the value differs from the snapshot):
//            SR8. Whether or not the reconcile was forced.
//   migrate  a state load or the first reconcile, with no fresh URL: resolve
//            the active source from the state's key, then the entry's key.
//   ignore   everything else, including the input going empty, which is the
//            ordinary steady state after the plugin's own strip.
//
// `adoptEpg` (R4) is decided the same way and independently of the playlist:
// a non-empty EPG input this service has not consumed is adopted into the
// ACTIVE record on any reconcile that sees it, "ignore" included, and taken
// out of the entry by the same owned write. D-SRC-10 ("an epgUrl that did not
// change in the write that changed the playlist was written for the previous
// source") is the same rule seen from the other side: an unchanged value is a
// consumed one. An EMPTY epg input is a no-op -- the CLI clear lever
// (`omarchy bar set ... epgUrl ""`) is withdrawn, the Sources screen clears a
// guide URL.
function reconcileAction(input) {
  var it = input || {}
  // R18a (round 8): both sides through the one normaliser, so "fresh" here
  // and "consumed" in retiredInputsToKeep can never disagree about a value
  // that differs only in its spacing.
  var playlist = entryInputForm("playlistUrl", it.playlist)
  var epg = entryInputForm("epgUrl", it.epg)
  var first = it.first === true
  var force = it.force === true
  // `first` carries no weight in "changed": the service's snapshot starts
  // "" and a value that equals "" is empty, so a first value is fresh by the
  // comparison alone. The term `first ||` used to sit here and a mutation
  // that dropped it reddened nothing (round 2 review, P3); `first` decides
  // `act` below and nothing else.
  var playlistChanged = playlist.form !== entryInputForm("playlistUrl", it.lastPlaylist).form
  var epgChanged = epg.form !== entryInputForm("epgUrl", it.lastEpg).form
  // `first` is handed back as it came (R20b, round 10): adoptActiveSource
  // judges an EPG input equal to the held one by the held one's time only
  // on the first reconcile after a start.
  var out = { act: "ignore",
              adoptUrl: playlist.text !== "" && playlistChanged,
              adoptEpg: epg.text !== "" && epgChanged,
              playlistChanged: playlistChanged, epgChanged: epgChanged, first: first }
  if (out.adoptUrl) out.act = "adopt"
  else if (first || force) out.act = "migrate"
  return out
}

// D-SINK-19. Resolve the active source, and migrate an install written by a
// build that named it by URL. ONE resolver for every reconcile: the shell
// start, a state load, a settings change (R1).
//
// `entry` is the host's bar entry as `settingsFrom` read it; `opts` is the
// plan reconcileAction made (`adoptUrl`, `adoptEpg`; both default to true so
// a caller with no plan gets the start-of-service behaviour). The order is
// the whole of the decision and each step is why the next is safe:
//
//   1. the entry's `playlistUrl`, when the plan says it is fresh. The ONLY
//      step that reads a URL. Validated; valid -> reconcileSources adopts it
//      exactly as it adopts a CLI value (SR8): a known URL becomes active, an
//      unknown one is added with origin "cli", or "migrated" on the very
//      first v2 run. Invalid -> `invalid` carries the result (D16) and the
//      resolution continues at step 2, so a typo leaves the active source
//      exactly as it was. The first version put this step LAST and returned
//      at step 2 before reaching it; see reconcileAction.
//   2. the state's own `activeKey`, when it names a record this state carries.
//   3. the entry's `sourceKey`, when it names a record. This is the mirror the
//      plugin writes; a POINTER and not a credential, so an install that lost
//      state.json's active key but still has its sources recovers.
//   4. nothing: no active source, and a dangling key is cleared rather than
//      left in the file for the next reader to resolve again.
//
// Then, whichever step answered, a fresh EPG input (R4) is adopted into the
// record that is now active, when it validates and differs from what the
// record holds.
//
// Returns { state, key, changed, moved, adoptedUrl, adoptedEpg, epgConsumed,
// invalid, added, evicted, writeEntry }. `changed` is whether the state must
// be written; `moved` is whether the active source is a DIFFERENT one than
// before, which is the only thing that resets the status line (the first
// version reset it on any input change, so a refused typo blanked a working
// source's status); `writeEntry` is whether the bar entry must be rewritten
// -- it still holds a playlist URL (fresh, stale or refused: a refused value
// can still carry credentials), an EPG input that REACHED a record
// (`epgConsumed`: adopted, already held, or refused -- there was an active
// record for it to land on), or its mirrored key disagrees with the state.
//
// R12 (round 3): an input is never stripped unadopted. R19b (round 9) keeps
// that and moves WHERE the unadopted EPG input waits: with NO active source
// to land on, a valid one is held in the state as `pendingEpg { url, seenAt }`
// (`pendedEpg`) and is then CONSUMED, so the owned write that follows the
// state save takes it off the entry; R12 left it on the entry, a possibly
// credentialed URL in shell.json for as long as no source existed. A refused
// one is consumed as refused (`refusedEpg`), as it is beside an active
// source. `opts.seenAt` (ms) is when the service saw the inputs: it becomes
// the adopted record's `epgSetAt`, or the pending value's `seenAt` (R19c).
// The first build stripped an unadopted input in the same write and the
// value was gone with no copy anywhere (round 2 review, P2); a held one has
// its copy in the state before the strip, because the strip waits for that
// save to land (R13).
function adoptActiveSource(state, entry, nowSec, origin, opts) {
  var st = state || emptyState()
  var e = entry || {}
  var o = opts || {}
  var adoptUrl = o.adoptUrl !== false
  var adoptEpg = o.adoptEpg !== false
  var before = activeKeyOf(st)
  // R19c: when this service first saw the inputs, in ms; 0 when the caller
  // has no clock (a record adopted then carries no epgSetAt and reads as 0).
  var seenAt = Math.max(0, Math.trunc(Number(o.seenAt)) || 0)
  var out = { state: st, key: "", changed: false, moved: false, adoptedUrl: false, adoptedEpg: false,
              epgConsumed: false, invalid: null, added: "", evicted: [], writeEntry: false,
              pendedEpg: false, refusedEpg: false, pendingApplied: false, pendingSuperseded: false }
  // R18a: the one normaliser (entryInputForm). `url` is the sanitized text
  // reconcileSources validates; `epg` is the whole form, so an EPG of
  // whitespace or control characters alone is NO input (R4's no-op) and not
  // the empty guide URL it used to validate as.
  var url = adoptUrl ? entryInputForm("playlistUrl", e.playlistUrl).text : ""
  var epg = adoptEpg ? entryInputForm("epgUrl", e.epgUrl) : entryInputForm("epgUrl", "")
  var resolved = false
  if (url !== "") {
    // Step 1. The EPG input is NOT handed to reconcileSources here: the R4
    // block below is the one place an EPG input reaches a record, whichever
    // step resolved the key, so there is one rule and not two.
    var rec = reconcileSources(st, url, "", before, nowSec, origin, { adoptEpg: false })
    if (rec.invalid) {
      out.invalid = rec.invalid
    } else {
      // The original object when nothing moved, so `changed` below stays an
      // honest "must this be written" and a consumed re-run saves nothing.
      out.state = rec.changed ? rec.state : st
      out.adoptedUrl = true
      out.added = rec.added
      out.evicted = rec.evicted
      resolved = true
    }
  }
  if (!resolved) {
    // Steps 2 to 4. activeKeyOf already refuses a key that names no record,
    // so "names a record" is the resolver's answer and not a second check.
    var stateKey = activeKeyOf(st)
    var entryKey = activeKeyText(e.sourceKey)
    var want = stateKey !== "" ? stateKey : (findSource(st.sources, entryKey) ? entryKey : "")
    out.state = withActiveKey(st, want)
  }
  out.key = activeKeyOf(out.state)
  // R20b (round 10): AT A START (`opts.atStart`, the first reconcile after
  // the service starts), an EPG input EQUAL to the guide URL the state
  // already holds as pending is that same input, still on the entry because
  // its strip never landed, and is judged with the time it was first seen
  // (its seenAt), never with now. The round-9 lens's P3: the pending E lost
  // to a later edit G by time just below, and the R4 block then took the
  // very same E as the latest input there is, seen now, and replaced G -- an
  // order state.json had already proved the other way.
  // NOT in session: there the service SAW the entry change to that value,
  // which is the user setting it again, a later explicit input (R19c). The
  // in-session reading was measured wrong by the round-9 lens's own matrix
  // (EPG:OLD:init 4 and EPG:OLD:cli 2 at length 2 on lane-key-z1's first
  // build: a CLI re-set of the held value lost to an older record time).
  // Usually the start never gets here: R20b's consumed slot proves the value
  // spent and reconcile does not call it fresh. This is the start over a
  // file with no slot -- one an earlier build wrote.
  var heldBefore = pendingEpgOf(st)
  var sameAsHeld = o.atStart === true && heldBefore !== null && epg.ok && epg.url === heldBefore.url
  // R19c: a guide URL held in the state for want of an active source
  // (R19b) meets the record that is active now -- the record a fresh URL
  // just named, or one a hand-edited file names beside it -- and the LATER
  // of the two inputs wins, by time (applyPendingEpg). Either way it is
  // cleared. Before the R4 block, so an input seen in this same reconcile,
  // which is later than anything pending, lands on top of the result.
  if (out.key !== "") {
    var applied = applyPendingEpg(out.state, out.key)
    out.state = applied.state
    out.pendingApplied = applied.applied
    out.pendingSuperseded = applied.superseded
  }
  // R4: a fresh EPG input reaches the ACTIVE record on any path -- the record
  // a fresh URL just named, a state load with an EPG on the entry, an
  // "ignore" plan that carries only an EPG change (D-SRC-02). R19c: it is
  // the latest explicit input there is, so it lands with its own seenAt as
  // the record's epgSetAt.
  if (adoptEpg && epg.text !== "" && out.key !== "") {
    out.epgConsumed = true
    var active = findSource(out.state.sources, out.key)
    // The guide URL the record ALREADY holds is not re-stamped: no held
    // value can be waiting for a record while one is active (R19b holds only
    // with none active, and every move clears it), so a later time on an
    // equal value is never compared with anything -- and the state write it
    // would cost defers the strip behind R13 for nothing (the round-9 matrix
    // measured a re-set of the same value made invisible that way).
    if (epg.ok && active && epg.url !== str(active.epgUrl)) {
      if (sameAsHeld) {
        // Already judged, by time, against this record a few lines up
        // (applyPendingEpg): it won and the record holds it, or it lost to
        // a later input and must not now win as "seen now".
        var judged = epgByTime(out.state, out.key, epg.url, heldBefore.seenAt)
        out.state = judged.state
        out.adoptedEpg = judged.won
      } else {
        var patch = { epgUrl: epg.url }
        if (seenAt > 0) patch.epgSetAt = seenAt
        out.state = replaceSource(out.state, out.key, patch)
        out.adoptedEpg = true
      }
    }
  } else if (adoptEpg && epg.text !== "") {
    // R19b: NO record can take it. A valid one is held in the state as
    // `pendingEpg` -- consumed, so the owned write that follows the save
    // takes it off the entry -- and a later one replaces an earlier one. A
    // refused one is consumed as refused, exactly as beside an active
    // source: reported, and written out (rule 5: a value that failed
    // validation can still carry a credential).
    out.epgConsumed = true
    if (epg.ok) {
      // R20b: the value already held keeps the time it was first seen.
      out.state = withPendingEpg(out.state, { url: epg.url, seenAt: sameAsHeld ? heldBefore.seenAt : seenAt })
      out.pendedEpg = true
    } else {
      out.refusedEpg = true
    }
  }
  out.changed = out.state !== st
  out.moved = out.key !== before
  // R12: `epgConsumed`, not "the entry carries an EPG". A consumed EPG input
  // (adopted, held already, or refused -- all three had a record to reach)
  // is taken out, and so is the host's stale echo of one consumed EARLIER
  // (the plan says `adoptEpg` false: it is not fresh, so it was adopted, rule
  // 9's one-write-behind host still publishing it). The one EPG that stays
  // is a FRESH one with no record to land on.
  var epgEcho = str(e.epgUrl) !== "" && !adoptEpg
  out.writeEntry = str(e.playlistUrl) !== "" || out.epgConsumed || epgEcho || activeKeyText(e.sourceKey) !== out.key
  return out
}

// D-SINK-19 round 7, R17b; round 9, R19c. THE ACTIVE MOVE MEETS A PENDING
// GUIDE URL.
//
// A guide URL input that arrived while no source was active is held in the
// state (R19b, `pendingEpg`; R12 kept it on the bar entry until round 9).
// Until round 7 only reconcile() attached it, and reconcile runs on a state
// load, a settings change and the shell's arrival -- never on the active key
// moving. So the moves (Service.switchSource, and the probe commit of an
// in-app add, an edit or a never-fetched switch) settle it themselves, in the
// SAME turn, before the state is saved and before the mirror is written.
//
// R19c: THE LATEST EXPLICIT INPUT WINS, BY TIME. Round 8 (R18d) let the add
// form's guide URL supersede a pending CLI value whenever the form carried
// one, without asking when either was made -- so a CLI epgUrl set while the
// add's probe ran, AFTER the submit, was dropped although it was the later
// input (round-8 data-loss lens, P1), and on the edit route the earlier
// pending value replaced a guide URL typed into the edit form after it (P2).
// Now every record carries `epgSetAt` (ms; set by the add form at SUBMIT, by
// the edit form, or by adoption with the input's seenAt) and the pending
// value lands on the newly active record iff its `seenAt` is LATER than the
// record's `epgSetAt` (absent = 0); otherwise the record keeps its own.
// Either way `pendingEpg` is cleared.
//
// `epgInput` / `lastEpg`: an input still FRESH on the entry (reconcile has
// not seen it; it always has once the state is loaded, so this is the
// defensive half) is first held exactly as reconcile would hold it, seen
// now (`nowMs`). A key that names no record moves nothing, and whatever is
// pending stays pending.
//
// -> { state, pending, consumed, refused, adopted, superseded, cleared }.
// `pending`: there was a fresh input on the entry. `consumed`: it was taken
// into the state (held or refused), and is what Model.epgSnapshotAfter moves
// the snapshot on. `adopted`: the pending value landed on the record.
// `superseded`: the record's own, later, guide URL won. `cleared`: there was
// a pending value and it is gone.
function adoptPendingEpg(state, key, epgInput, lastEpg, nowMs) {
  var st = state || emptyState()
  var out = { state: st, pending: false, consumed: false, refused: false, adopted: false, superseded: false, cleared: false }
  var plan = reconcileAction({ playlist: "", epg: epgInput, lastPlaylist: "", lastEpg: lastEpg })
  out.pending = plan.adoptEpg === true
  var k = activeKeyText(key)
  if (k === "" || !findSource(st.sources, k)) return out
  if (out.pending) {
    var f = entryInputForm("epgUrl", epgInput)
    out.consumed = true
    if (f.ok) st = withPendingEpg(st, { url: f.url, seenAt: Math.max(0, Math.trunc(Number(nowMs)) || 0) })
    else out.refused = true
  }
  var applied = applyPendingEpg(st, k)
  out.state = applied.state
  out.adopted = applied.applied
  out.superseded = applied.superseded
  out.cleared = applied.cleared
  return out
}

// R19c's one comparison. `url`, set at `setAt` (ms), lands on record `key`
// iff `setAt` is LATER than the record's own epgSetAt (absent = 0); an equal
// time is not later. -> { state, won }; the same state object when it loses
// or there is no such record. The S5 `known` branch of the probe commit
// lands the form's guide URL through this too (OQ-X3 ruled): the record the
// commit keeps takes it only if it was set later than whatever that record
// already holds.
function epgByTime(state, key, url, setAt) {
  var st = state || emptyState()
  var k = activeKeyText(key)
  var rec = k === "" ? null : findSource(st.sources, k)
  var at = Math.max(0, Math.trunc(Number(setAt)) || 0)
  if (!rec || !(at > epgSetAtOf(rec))) return { state: st, won: false }
  return { state: replaceSource(st, k, { epgUrl: str(url), epgSetAt: at }), won: true }
}

// R19c: the pending guide URL meets record `key` (epgByTime) and is
// cleared. Nothing pending, or no such record: nothing moves.
// -> { state, applied, superseded, cleared }.
function applyPendingEpg(state, key) {
  var st = state || emptyState()
  var pending = pendingEpgOf(st)
  var k = activeKeyText(key)
  if (pending === null || k === "" || !findSource(st.sources, k)) return { state: st, applied: false, superseded: false, cleared: false }
  var r = epgByTime(st, k, pending.url, pending.seenAt)
  return { state: withPendingEpg(r.state, null), applied: r.won, superseded: !r.won, cleared: true }
}

// Service.activeEpgUrl's decision, lifted so node can call it (rule 12; the
// round-8 lens's a12 mutation reverted the inline read and nothing went red).
// The guide URL the user set for the active source: the record's own once
// there is a record. Before that, an input on the entry (it is about to be
// held), else the one held in the state (R19b). Beside a record, an input
// that is SOMETHING but does not validate is returned as it is, so the
// helper reports it (D16's shape); an input of whitespace or control
// characters alone is NO input (R18a) and the record's value stands.
function activeEpgUrlOf(record, input, pending) {
  var f = entryInputForm("epgUrl", input)
  if (!record) {
    if (f.text !== "") return str(input)
    var p = pendingEpgRecord(pending)
    return p ? p.url : ""
  }
  if (f.text !== "" && !f.ok) return str(input)
  return str(record.epgUrl)
}

// D-SINK-19 repair, R5 and R13. THE ORDER OF THE TWO WRITES A POINTER
// CHANGE MAKES.
//
// A move of the active source is two writes: the key into state.json (the
// authority) and the mirror into the bar entry, which is also the write that
// takes a URL OUT of that entry. The first version wrote the entry through
// Qt.callLater ungated while the state save could still be DEFERRED (dirs
// not ready at start-up: saveState() parks the write behind stateInitProc),
// so a shell that died between the two left the URL gone from the entry and
// no key in the state -- a source nobody points at, with nothing left to
// re-adopt from.
//
// The state is saved FIRST and the entry write WAITS for the save to LAND
// (R13: on EVERY route, not only the parked one). R11 gated the parked
// route on the FileView's `saved`; the dirsReady route still wrote the
// entry straight after setText, and a state write that then FAILED (a full
// disk, an unwritable ~/.local/state) had already stripped the URL from the
// host's file: the record existed in memory only and the input had no copy
// anywhere (round-3 review P1, measured live). So an entry step is
// immediate ONLY when nothing of ours is outstanding -- no save parked, none
// in flight, and the last one did not fail. Otherwise the key is HELD and
// Model.entryFlushDisposition settles it from `saved` / `saveFailed`: on any
// failure the URL stays on the entry as the backup it accidentally is, and
// the next start re-adopts it (R1).
//
// `steps` is executed in order by Service.persistActive:
//   save-state              assign the state and call saveState() (which
//                           writes now)
//   defer-state             the same call, which parks the write until the
//                           dirs are ready; named separately so a test can
//                           see the difference
//   write-entry             mirror the key into the entry now: the file
//                           already says what memory says
//   write-entry-after-saved hold the key; the FileView's `saved` (or
//                           `saveFailed`) settles it through
//                           Model.entryFlushDisposition (R13). Also the
//                           answer when the LAST save failed and nothing is
//                           in flight: the file is older than memory, the
//                           disposition drops the hold at once and the URL
//                           stays on the entry
//   wait-entry              hold the key; stateInitProc's exit writes the
//                           parked state and the same disposition settles it
//                           once that save lands (R11)
// `entryWaits` is true whenever the entry is held rather than written.
// In the model rather than inline so node can call it (rule 12); the shared
// fixture's `order` cases pin every combination.
function pointerWritePlan(input) {
  var it = input || {}
  var keyMoved = it.keyMoved === true
  var dirsReady = it.dirsReady === true
  var savePending = it.savePending === true
  var inFlight = (Number(it.savesInFlight) || 0) > 0
  var saveFailed = it.saveFailed === true
  if (keyMoved) {
    return dirsReady ? { steps: ["save-state", "write-entry-after-saved"], entryWaits: true }
                     : { steps: ["defer-state", "wait-entry"], entryWaits: true }
  }
  // Nothing of ours to save, unless an EARLIER save is still parked: then the
  // entry must not get ahead of it. With the dirs ready that park is flushed
  // right here rather than waited on, because nothing else would wake the
  // wait (stateInitProc's exit has already run) -- and the entry still waits
  // for that flush to land.
  if (savePending) {
    return dirsReady ? { steps: ["save-state", "write-entry-after-saved"], entryWaits: true }
                     : { steps: ["wait-entry"], entryWaits: true }
  }
  // R13: a save issued by the caller a moment ago (adoptActive saves, then
  // persistActive runs from Qt.callLater with the key already in memory) is
  // in flight here with the key unmoved. That was the round-3 P1: the plan
  // read "nothing to save" and wrote the entry before that save landed.
  if (inFlight || saveFailed) return { steps: ["write-entry-after-saved"], entryWaits: true }
  return { steps: ["write-entry"], entryWaits: false }
}

// R12's other half. The service keeps a snapshot of the last EPG input it saw
// (reconcileAction compares against it, so a value is adopted once and the
// host's stale echo of it, rule 9, is not adopted twice). The snapshot moves
// to the input only when the input was CONSUMED (adoptActiveSource's
// `epgConsumed`) or when the input went away. Since R19b every non-empty
// fresh input is consumed when it is seen -- onto the active record, into
// the state's `pendingEpg`, or refused -- so the "left fresh" branch is now
// reached only by an input reconcile did not ask about; it is kept because
// that is still the right answer for one.
function epgSnapshotAfter(epg, lastEpg, consumed) {
  var now = str(epg)
  if (now === "" || consumed === true) return now
  return str(lastEpg)
}

// `activeSourceKey(state, playlistUrl)` USED TO BE HERE and is deliberately
// gone (D-SINK-19, rule 15). It was the one function whose job was "name the
// active source from a URL", and leaving it behind with no caller would leave
// the defect one call away: the next reader needing the active key would find
// a function that takes the setting and returns it. Identity by URL survives
// where it belongs -- `findSourceByUrl` for duplicate detection and for
// `reconcileSources` adopting a CLI value (D4's identity half, untouched) --
// and the active source is `activeKeyOf(state)`.
//
// SR11 is unaffected: a `~` path set through `omarchy bar set` still resolves
// to its record, because `reconcileSources` is what resolves it and it still
// validates with `origin: "cli"`.

// D3 / SR8, narrowed by D-SINK-19: a playlist URL INPUT names the active
// source; the history follows and the key is written INTO the returned state
// (R2 -- the first version returned it as an out-param only and
// Service.reconcile never wrote it, so on a configured install the active
// source never moved on this path). A known URL bumps `lastUsed` only when
// the active key actually changed and adopts a changed (valid) EPG URL; an
// unknown URL is added with a derived label and `origin` "migrated" on the
// very first v2 run (no history, legacy cache layout) or "cli" afterwards.
// Beyond MAX_SOURCES the least recently used non-active records are evicted.
// `invalid` carries the validation result for a set but invalid URL (D16).
// `opts.adoptEpg === false` (D-SRC-10): the settings' epgUrl was written
// for the previous source (it did not change in the settings write that
// changed the playlist), so a known record keeps its own epgUrl and a new
// record starts without one; the default adopts it (a CLI `epgUrl` change,
// D-SRC-02, or the first reconcile after a state load).
function reconcileSources(state, playlistUrl, epgUrl, previousActiveKey, nowSec, origin, opts) {
  var st = cloneState(state)
  var out = { state: st, changed: false, activeKey: "", added: "", evicted: [], invalid: null }
  var raw = sanitizeInput(playlistUrl, MAX_SOURCE_URL + 1)
  if (raw === "") return out
  // The settings are the CLI path: `~` paths stay accepted here (SR11,
  // no 0.1.0 regression) while the forms keep refusing them.
  var pv = validateSourceUrl(raw, { origin: "cli" })
  if (!pv.ok) { out.invalid = pv; return out }
  var adoptEpg = !(opts && opts.adoptEpg === false)
  var ev = validateSourceUrl(epgUrl, { kind: "epg", origin: "cli" })
  var epg = adoptEpg && ev.ok ? ev.url : ""
  var now = nowInt(nowSec)
  var rec = findSourceByUrl(st.sources, pv.url)
  if (rec) {
    var patch = {}
    if (str(rec.key) !== str(previousActiveKey)) patch.lastUsed = now
    if (adoptEpg && ev.ok && epg !== str(rec.epgUrl)) patch.epgUrl = epg
    var keys = 0
    for (var k in patch) keys++
    if (keys > 0) { out.state = replaceSource(st, rec.key, patch); out.changed = true }
    out.activeKey = str(rec.key)
    // R2: the key lives where the state lives. withActiveKey returns the same
    // object when the key is already this one, so `changed` stays honest.
    out.state = withActiveKey(out.state, out.activeKey)
    out.changed = out.changed || out.state !== st
    return out
  }
  var kind = str(origin) !== "" && SOURCE_ORIGINS.indexOf(str(origin)) !== -1 ? str(origin) : (st.sources.length === 0 && st.cacheLayout !== CACHE_LAYOUT ? "migrated" : "cli")
  var key = allocateSourceKey(st.sources, pv.url)
  var record = {
    key: key, url: pv.url, epgUrl: epg, kind: pv.kind,
    label: uniqueLabel(deriveLabel(pv.url, pv.kind), sourceLabels(st)), labelCustom: false,
    origin: kind, addedAt: now, lastUsed: now, fetchedAt: 0, channelCount: 0, groupCount: 0
  }
  var sources = st.sources.concat([record])
  while (sources.length > MAX_SOURCES) {
    var victim = -1
    for (var i = 0; i < sources.length; i++) {
      if (sources[i].key === key) continue
      if (victim === -1 || Number(sources[i].lastUsed) < Number(sources[victim].lastUsed)) victim = i
    }
    if (victim === -1) break
    out.evicted.push(str(sources[victim].key))
    sources.splice(victim, 1)
  }
  out.state = withActiveKey(cloneState(st, { sources: sources }), key)
  out.changed = true
  out.activeKey = key
  out.added = key
  return out
}

// The only function that hands a URL to the guide: the edit form's values.
function sourceForEdit(state, key) {
  var rec = findSource(state ? state.sources : [], key)
  if (!rec) return null
  var view = sourceView(rec, "", 0, "")
  return {
    id: str(rec.key), key: str(rec.key), label: str(rec.label), labelCustom: rec.labelCustom === true,
    kind: view.kind, host: view.host, origin: str(rec.origin),
    playlistUrl: str(rec.url), epgUrl: str(rec.epgUrl),
    playlistMasked: maskUrl(rec.url), epgMasked: maskUrl(rec.epgUrl)
  }
}

// IPC `status` list: label / host / counts, never a URL.
function sourcesSummary(state, activeKey) {
  var views = sourceViews(state, activeKey, 0, null)
  var out = []
  for (var i = 0; i < views.length; i++) {
    out.push({ id: views[i].id, key: views[i].id, label: views[i].label, host: views[i].host, active: views[i].active, channelCount: views[i].channelCount, lastUsed: views[i].lastUsedAt })
  }
  return out
}

// Full bar entry for `shell.updateEntryInline`: every own key of `entry`
// copied (keys we do not own must survive the wholesale replace) EXCEPT the
// retired URL keys, `patch` applied, `id` forced.
//
// D-SINK-19. The host builds the stored entry as `{id} + everything in what
// we hand it` (shell.qml:1092-1093), so a key we leave out is a key that is
// GONE from the file -- which is how the credential actually leaves, rather
// than being overwritten with an empty string that still says what shape the
// old entry had. A `patch` may name a retired key explicitly and that value
// wins; nothing in this repository does, and the test that proves it calls
// `ownedEntryPatch` rather than grepping for the names.
//
// R16: `opts.keepRetired === true` carries the retired keys over UNCHANGED.
// That is the patch-only write (Service.setShowLogos before the first state
// load or while a state write is outstanding, `ownedWriteMode`): "unchanged"
// means as `entry` carries them, and the service hands this the PUBLISHED
// entry, which the lagging host leaves one write behind (D-SINK-20). The
// URL on the entry may be the only copy
// of a source whose state write has not landed, and a write that takes it
// off is the key mirror's to make, after the save lands. The default is
// still removal, because the default is what the mirror and the settled
// toggle use.
//
// R20c (round 10): the service no longer passes `keepRetired` at all; the
// patch-only write hands the keep list Model.patchInputsToKeep answers, and
// `keepRetired` stays for a caller that means "every one".
//
// R17a (round 7): `opts.keep`, an array of retired key names, carries THOSE
// over unchanged on any write, heal included. The service passes
// Model.retiredInputsToKeep's answer on every owned write, so a retired key
// is removed only when it is consumed: a record holds it, or the service
// already consumed it. `keepRetired` still keeps all of them, which is what
// the patch-only write needs (a record in memory whose state write has not
// landed is not yet a reason to strip).
function entryWith(entry, patch, opts) {
  var out = {}
  var src = entry && typeof entry === "object" ? entry : {}
  var keepAll = !!(opts && opts.keepRetired === true)
  var keep = opts && Object.prototype.toString.call(opts.keep) === "[object Array]" ? opts.keep : []
  for (var k in src) if (keepAll || RETIRED_SETTINGS.indexOf(k) === -1 || keep.indexOf(k) !== -1) out[k] = src[k]
  var p = patch || {}
  for (var q in p) out[q] = p[q]
  if (str(out.id) === "" && str(src.id) !== "") out.id = str(src.id)
  return out
}

// A cache is stale when its status is not ok, has no fetchedAt, or is older
// than refreshMinutes.
function cacheStale(status, refreshMinutes, nowSec) {
  if (!status || status.ok !== true) return true
  var fetched = Number(status.fetchedAt) || 0
  if (fetched <= 0) return true
  var minutes = clampSetting("refreshMinutes", refreshMinutes)
  return (Number(nowSec) || 0) - fetched >= minutes * 60
}

// ---- form state and the Sources transitions (UX-SOURCES 1.9, 2.3, 7.3)
//
// form = { kind: "url" | "xtream", origin: "firstRun" | "sources", sourceId,
//          values: { label, playlist, epg } | { label, server, username, password },
//          original: the values the edit form opened with, focus: element id,
//          revealed: { playlist, epg } (true = raw value shown / typed),
//          error: null | { code, field, message }, probing, probeHost,
//          probeKind, parent: the form to return to (Xtream from a URL form) }

function formFields(form) {
  var f = form || {}
  if (f.kind === "xtream") return ["label", "server", "username", "password"]
  return f.origin === "firstRun" ? ["playlist", "epg"] : ["label", "playlist", "epg"]
}

function isFormField(form, id) {
  return formFields(form).indexOf(str(id)) !== -1
}

// The validation cap of a field (LIMITS, SR5).
function formLimit(field) {
  return FORM_LIMITS[str(field)] || MAX_SOURCE_URL
}

// What a field may hold: the cap plus slack, so an over-cap paste is kept
// long enough to be refused with `too_long` / `label_too_long` /
// `user_too_long` instead of being cut silently (SR18, SR22).
var FORM_SLACK = 64

function formCapacity(field) {
  return formLimit(field) + FORM_SLACK
}

function emptyValues(kind) {
  if (kind === "xtream") return { label: "", server: "", username: "", password: "" }
  return { label: "", playlist: "", epg: "" }
}

function copyValues(kind, values) {
  var out = emptyValues(kind)
  var src = values || {}
  for (var k in out) out[k] = str(src[k])
  return out
}

